namespace RealEstatePro\Ai;defined('ABSPATH')||exit;final class OpenAIProvider implements ProviderInterface{public function chat(string $system,string $user,array $options=[]):array{$key=get_option('re_pro_openai_key','');if(!$key)throw new \RuntimeException('OpenAI API key is not configured.');$body=['model'=>$options['model']??'gpt-4o-mini','messages'=>[['role'=>'system','content'=>$system],['role'=>'user','content'=>$user]],'temperature'=>0.2];$r=wp_remote_post('https://api.openai.com/v1/chat/completions',['timeout'=>30,'headers'=>['Authorization'=>'Bearer '.$key,'Content-Type'=>'application/json'],'body'=>wp_json_encode($body)]);if(is_wp_error($r))throw new \RuntimeException($r->get_error_message());$d=json_decode(wp_remote_retrieve_body($r),true);return ['text'=>$d['choices'][0]['message']['content']??'','usage'=>$d['usage']??[]];}}